#include <memory>
#include <iostream>

// A class with custom memory management that only handles its own size.
class Widget {
public:
    static void* operator new(std::size_t size) {
        std::cout << "Custom new called, size = " << size << std::endl;
        if (size != sizeof(Widget)) {
            std::cout << "  Warning: size is not sizeof(Widget)!\n";
        }
        return ::operator new(size);
    }
    static void operator delete(void* p) {
        std::cout << "Custom delete called.\n";
        ::operator delete(p);
    }
};

void demonstrate_custom_new() {
    // Correct usage: invokes custom new with the expected size.
    std::shared_ptr<Widget> spw1(new Widget);

    // Problematic usage: std::make_shared would request a single block for
    // both the Widget and the control block. The size passed to `operator new`
    // would be > sizeof(Widget), potentially breaking its assumptions.
    // auto spw2 = std::make_shared<Widget>(); // This is unsafe and should be avoided.
}
